// n8n Code Node: Summarize User Context with Trends
// References nodes by name — no input order dependency

const coaches = $('Recent_coaches').all().map(i => i.json);
  const checkins = $('Checkin_Data').all().map(i => i.json);
const wol = $('wol_data').all().map(i => i.json);

// --- Coach ---
const coachLine = coaches.length > 0
  ? `Coach: ${coaches[0].first_name} ${coaches[0].last_name} (${coaches[0].email})`
  : "Coach: Not assigned";

// --- Check-in Timeline ---
let checkinBlock = "Recent check-ins: No data available";
if (checkins.length > 0) {
  const addiction = checkins[0].addiction || "Not specified";
  const avg = parseFloat(checkins[0].score_avg).toFixed(1);
  const stddev = parseFloat(checkins[0].score_stddev).toFixed(1);

  const timeline = checkins.slice(0, 10).map((c, i) => {
    const parts = [];
    if (c.score !== null && c.score !== undefined) parts.push(`Score: ${c.score}`);
    if (c.i_am) parts.push(`"${c.i_am}"`);
    if (c.positive) parts.push(`+${c.positive}`);
    if (c.negative) parts.push(`-${c.negative}`);
    const label = i === 0 ? "(most recent)" : "";
    return `  ${i + 1}. ${parts.join(" | ")} ${label}`;
  });

  const scores = checkins
    .slice(0, 10)
    .map(c => c.score)
    .filter(s => s !== null && s !== undefined);

  let trajectory = "";
  if (scores.length >= 2) {
    const recent = scores.slice(0, Math.min(3, scores.length));
    const older = scores.slice(Math.min(3, scores.length));
    const recentAvg = recent.reduce((a, b) => a + b, 0) / recent.length;
    const olderAvg = older.length > 0
      ? older.reduce((a, b) => a + b, 0) / older.length
      : null;

    if (olderAvg !== null) {
      const diff = recentAvg - olderAvg;
      if (diff > 5) trajectory = "Trend: Improving ↑";
      else if (diff < -5) trajectory = "Trend: Declining ↓";
      else trajectory = "Trend: Stable →";
    }
  }

  checkinBlock = [
    `Addiction focus: ${addiction}`,
    `Overall avg: ${avg} (stddev: ${stddev})`,
    trajectory,
    `Check-in history (newest first):`,
    ...timeline
  ].filter(Boolean).join("\n");
}

// --- Wheel of Life Timeline ---
let wolBlock = "Wheel of Life: No data available";
if (wol.length > 0) {
  const wolFields = [
    "purpose", "contribution", "business", "finance",
    "health", "family_friends", "romance",
    "personal_growth", "fun_recreation", "physical_environment"
  ];

  const formatLabel = (f) => f.replace(/_/g, " ");

  // Deduplicate by score_date
  const seen = new Set();
  const uniqueWol = wol.filter(w => {
    const key = w.score_date;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });

  const assessments = uniqueWol.slice(0, 6).map((entry, i) => {
    const date = entry.score_date
      ? new Date(entry.score_date).toLocaleDateString()
      : "Unknown";

    const scores = wolFields
      .filter(f => entry[f] !== null && entry[f] !== undefined)
      .map(f => `${formatLabel(f)}: ${entry[f]}`)
      .join(", ");

    const label = i === 0 ? "(most recent)" : "";
    return `  ${date} ${label}\n    ${scores}`;
  });

  // Trend: compare latest vs oldest
  let trendSummary = "";
  if (uniqueWol.length >= 2) {
    const latest = uniqueWol[0];
    const oldest = uniqueWol[uniqueWol.length - 1];

    const improving = [];
    const declining = [];
    const stable = [];

    wolFields.forEach(f => {
      if (latest[f] == null || oldest[f] == null) return;
      const diff = latest[f] - oldest[f];
      const label = formatLabel(f);
      if (diff >= 2) improving.push(`${label} (+${diff})`);
      else if (diff <= -2) declining.push(`${label} (${diff})`);
      else if (latest[f] <= 4) stable.push(`${label} (stuck at ${latest[f]})`);
    });

    const trendParts = [];
    if (improving.length) trendParts.push(`Improving: ${improving.join(", ")}`);
    if (declining.length) trendParts.push(`Declining: ${declining.join(", ")}`);
    if (stable.length) trendParts.push(`Stuck low: ${stable.join(", ")}`);

    if (trendParts.length) {
      trendSummary = `Overall trends:\n  ${trendParts.join("\n  ")}`;
    }
  }

  const latest = uniqueWol[0];
  const scored = wolFields
    .filter(f => latest[f] !== null && latest[f] !== undefined)
    .map(f => ({ field: formatLabel(f), score: latest[f] }));

  const highs = scored.filter(s => s.score >= 8).map(s => s.field);
  const lows = scored.filter(s => s.score <= 5).map(s => `${s.field} (${s.score})`);

  wolBlock = [
    `Wheel of Life assessments (newest first):`,
    ...assessments,
    "",
    highs.length > 0 ? `Current strengths (8+): ${highs.join(", ")}` : "",
    lows.length > 0 ? `Current concerns (≤5): ${lows.join(", ")}` : "",
    trendSummary
  ].filter(Boolean).join("\n");
}

// --- Assemble ---
const contextBlock = `## User Context
${coachLine}

### Check-in History
${checkinBlock}

### Life Balance (Wheel of Life)
${wolBlock}`;

return [{ json: { user_context: contextBlock } }];

